%%EmilijusGureckas, LD6, 3Var
clearvars
close all
clc

%% 1 uzduotis - kauliukai

help kauliukai %[output:05ad4270]
[k1, k2] = kauliukai %[output:5b6f991a] %[output:763b9827]

%% 2 uzduotis - globalus kintamieji

global x y

x = 2*pi:-0.1:-2*pi;
y = zeros(size(x));

neigiamaDalis
teigiamaDalis

whos global %[output:64191e80]

plot(x, y, 'k-.+') %[output:28c4ce58]
xlabel('x') %[output:28c4ce58]
ylabel('y(x)') %[output:28c4ce58]
title('Funkcijos y(x) grafikas') %[output:28c4ce58]
grid on %[output:28c4ce58]

